import 'dart:convert';
import 'dart:ui';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import 'i18n.dart';

/// One game in the factory, from assets/apps.json (generated by
/// `python3 tool/factory.py --root games` from `games/apps/<id>.json`).
class GameConfig {
  GameConfig({
    required this.id,
    required this.game,
    required this.title,
    required this.color,
    required this.premiumProductId,
    required this.privacyPolicyUrl,
    required this.supportEmail,
  });

  final String id;

  /// Engine: queens, pips, patches, weave, putt.
  final String game;
  final Map<String, String> title;
  final Color color;
  final String premiumProductId;
  final String privacyPolicyUrl;
  final String supportEmail;

  String titleFor(String lang) => title[lang] ?? title['en'] ?? id;

  factory GameConfig.fromJson(Map<String, dynamic> j) => GameConfig(
    id: j['id'] as String,
    game: j['game'] as String,
    title: Map<String, String>.from(j['title'] as Map),
    color: Color(
      int.parse((j['color'] as String).substring(1), radix: 16) | 0xFF000000,
    ),
    premiumProductId: j['premiumProductId'] as String,
    privacyPolicyUrl: j['privacyPolicyUrl'] as String,
    supportEmail: j['supportEmail'] as String,
  );

  static Future<GameConfig> load() async {
    final all =
        jsonDecode(await rootBundle.loadString('assets/apps.json'))
            as Map<String, dynamic>;
    const fromDefine = String.fromEnvironment('APP_ID');
    final fromUrl = kIsWeb ? Uri.base.queryParameters['app'] : null;
    final id = fromUrl != null && all.containsKey(fromUrl)
        ? fromUrl
        : fromDefine.isNotEmpty
        ? fromDefine
        : (appFlavor != null && all.containsKey(appFlavor))
        ? appFlavor!
        : all.keys.first;
    return GameConfig.fromJson(all[id] as Map<String, dynamic>);
  }
}

/// UI language from the device, limited to the languages we ship.
String deviceLang() {
  final supported = T.languages.toSet();
  final code = PlatformDispatcher.instance.locale.languageCode;
  if (kIsWeb) {
    final q = Uri.base.queryParameters['lang'];
    if (q != null && supported.contains(q)) return q;
  }
  return supported.contains(code) ? code : 'en';
}
